SELECT * FROM agent_tool WHERE active = 1 AND (is_public = 1 OR creator = #{currentUsername})
AND (name LIKE CONCAT('%', #{keyword}, '%') OR display_name LIKE CONCAT('%', #{keyword}, '%') OR description LIKE CONCAT('%', #{keyword}, '%'))
AND status = #{status}
AND type = #{type}
ORDER BY status DESC, update_time DESC
